// Procedural browser visualization of the owner's LangGraph orchestration.
// It demonstrates geometry, routing and repair locally; it does not call an LLM or Blender.
(()=>{const canvas=document.querySelector('#agent-scene');if(!canvas)return;const ctx=canvas.getContext('2d');const button=document.querySelector('#generate-scene'),selector=document.querySelector('#scene-scenario'),lessMotion=matchMedia('(prefers-reduced-motion: reduce)').matches;
let view="scene",zoom=1,pointSize=2; let width=0,height=0,angle=-.62,running=false,phase='idle',seed=0,scene=null,points=[],layers=new Set(),showBox=false;const stages=['planner','builder','validator','repair','sensor','dataset','exporter'];const complete=new Set();let solids=[];
const palette={ground:['#426d61','#294e49','#1e3d3e'],rail:['#a9bac0','#6f8f9a','#56747e'],wood:['#a8885c','#80603f','#654a33'],wall:['#e8ddc0','#c1b997','#969d83'],roof:['#83a3a6','#587b85','#3e616e'],leaf:['#80aa7c','#537f68','#3b6155'],trunk:['#ad8a5e','#7e623f','#635138'],sensor:['#baaadf','#9283b8','#716895']};
const inviteObserver=new IntersectionObserver(entries=>{if(entries.some(e=>e.isIntersecting)){button.classList.add('demo-visible');inviteObserver.disconnect()}},{threshold:.7});inviteObserver.observe(button);
const delay=ms=>new Promise(resolve=>setTimeout(resolve,lessMotion?Math.min(ms,90):ms));
function random(){seed=(seed*1664525+1013904223)>>>0;return seed/4294967296}
function specFor(mode,initialSeed){seed=initialSeed;const s={seed:initialSeed,scenario:mode,curved:mode==='curved',shelter:{x:.5,z:-1.2,w:2.4,d:1.8,h:1.7},sensor:{x:-3,z:3,h:1.1},trees:[],repairs:0};for(let i=0;i<5;i++)s.trees.push({x:3.4+random()*.8,z:-2.7+random()*5,r:.5});if(mode==='occluded')s.trees.push({x:-.65,z:1.15,r:.8});return s}
function distanceToSegment(p,a,b){const dx=b.x-a.x,dz=b.z-a.z,t=Math.max(0,Math.min(1,((p.x-a.x)*dx+(p.z-a.z)*dz)/(dx*dx+dz*dz)));return Math.hypot(p.x-(a.x+t*dx),p.z-(a.z+t*dz))}
function blockers(s){const target={x:s.shelter.x+s.shelter.w/2,z:s.shelter.z+s.shelter.d/2};return s.trees.filter(t=>distanceToSegment(t,s.sensor,target)<t.r+.1)}
function status(role,action,detail){phase=role;document.querySelector('#agent-action').textContent=action;document.querySelector('#agent-detail').textContent=detail;document.querySelector('#scene-stage').textContent=role==='done'?'Scene ready':role==='idle'?'Ready to build':role.charAt(0).toUpperCase()+role.slice(1)+' working';stages.forEach(id=>{const el=document.querySelector(`[data-agent="${id}"]`),done=complete.has(id);el.classList.toggle('working',id===role);el.classList.toggle('finished',done);const mark=el.querySelector('i');mark.textContent=id===role?'●':done?'✓':'○';mark.setAttribute('aria-label',id===role?'Working':done?'Finished':'Waiting')});draw()}
function record(){if(!scene)return;document.querySelector('#scene-record').textContent=JSON.stringify({seed:scene.seed,scene_spec:{track:scene.curved?'curved':'straight',shelter:scene.shelter,trees:scene.trees.map(t=>({x:+t.x.toFixed(2),z:+t.z.toFixed(2)}))},validation_errors:blockers(scene).length?['sensor_view_blocked']:[],attempt_count:scene.repairs,sample_points:points.length,modalities:['scene_image','point_cloud','object_labels'],coordinate_frame:'shared scene coordinates',label:{class:'bungalow',position:[scene.shelter.x,0,scene.shelter.z],dimensions:[scene.shelter.w,scene.shelter.h,scene.shelter.d]},status:phase},null,2)}
function p(x,y,z){const a=x*Math.cos(angle)-z*Math.sin(angle),b=x*Math.sin(angle)+z*Math.cos(angle),k=Math.min(width/13,height/7)*zoom;return{x:width*.5+a*k,y:height*.55+b*k*.48-y*k,depth:b+y*.001}}
function box(x,y,z,w,h,d,color){solids.push({x,y,z,w,h,d,c:palette[color]||color})}
function poly(vertices,color,stroke='#1c3d4520'){ctx.beginPath();vertices.forEach((v,i)=>i?ctx.lineTo(v.x,v.y):ctx.moveTo(v.x,v.y));ctx.closePath();ctx.fillStyle=color;ctx.fill();ctx.strokeStyle=stroke;ctx.lineWidth=.6;ctx.stroke()}
function addTree(t){box(t.x,0,t.z,.17,1.3,.17,'trunk');box(t.x-t.r*.7,1,t.z-t.r*.7,t.r*1.6,.8,t.r*1.6,'leaf');box(t.x-t.r*.4,1.8,t.z-t.r*.4,t.r,.5,t.r,'leaf')}
function draw(){if(scene)readout();ctx.clearRect(0,0,width,height);ctx.fillStyle='#102d3d';ctx.fillRect(0,0,width,height);ctx.strokeStyle='#315365';ctx.lineWidth=1;for(let i=-5;i<=5;i++){const a=p(i,-.3,-4),b=p(i,-.3,4);ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.stroke();const c=p(-5,-.3,i*.8),d=p(5,-.3,i*.8);ctx.beginPath();ctx.moveTo(c.x,c.y);ctx.lineTo(d.x,d.y);ctx.stroke()}
if(!scene){ctx.fillStyle='#a0c5cf';ctx.font='14px Arial';ctx.textAlign='center';ctx.fillText('The scene will take shape here.',width/2,height/2);return}
solids=[];box(-4.8,-.35,-3.5,9.6,.3,7,'ground');if(layers.has('track'))for(let i=0;i<16;i++){const z=-3.2+i*.4,offset=scene.curved?Math.sin((i/15)*2.2)*1.1:0;box(-3.5+offset,0,z,1.4,.1,.16,'wood');box(-3.38+offset,.1,z,.1,.13,.44,'rail');box(-2.35+offset,.1,z,.1,.13,.44,'rail')}
const b=scene.shelter;if(layers.has('shelter')){box(b.x,0,b.z,b.w,b.h,b.d,'wall');box(b.x-.16,b.h,b.z-.16,b.w+.32,.25,b.d+.32,'roof');box(b.x+.35,0,b.z+b.d+.01,.5,1.05,.03,'roof');box(b.x+1.45,.65,b.z+b.d+.02,.5,.5,.03,['#c8e4da','#a6d3c9','#7baca4'])}if(layers.has('trees'))scene.trees.forEach(addTree);if(layers.has('sensor')){const s=scene.sensor;box(s.x,0,s.z,.14,1,.14,'rail');box(s.x-.23,1,s.z-.23,.6,.28,.6,'sensor')}
const faces=[];solids.forEach(({x,y,z,w,h,d,c})=>{const add=(v,color)=>faces.push({v,color,depth:v.reduce((sum,v)=>sum+v.depth,0)/v.length});add([p(x,y+h,z),p(x+w,y+h,z),p(x+w,y+h,z+d),p(x,y+h,z+d)],c[0]);add([p(x,y,z+d),p(x+w,y,z+d),p(x+w,y+h,z+d),p(x,y+h,z+d)],c[1]);if(Math.sin(angle)<0)add([p(x,y,z),p(x,y,z+d),p(x,y+h,z+d),p(x,y+h,z)],c[2]);else add([p(x+w,y,z),p(x+w,y,z+d),p(x+w,y+h,z+d),p(x+w,y+h,z)],c[2])});faces.sort((a,b)=>a.depth-b.depth);if(view!=='cloud')faces.forEach(f=>poly(f.v,f.color));
if(points.length){if(view==='cloud')points.forEach(v=>{const q=p(v.x,v.y,v.z);ctx.fillStyle=v.color;ctx.fillRect(q.x-pointSize/2,q.y-pointSize/2,pointSize,pointSize)});const s=p(scene.sensor.x,scene.sensor.h,scene.sensor.z),target=p(b.x+b.w/2,.85,b.z+b.d);ctx.setLineDash([5,5]);ctx.strokeStyle='#b5a5e1';ctx.beginPath();ctx.moveTo(s.x,s.y);ctx.lineTo(target.x,target.y);ctx.stroke();ctx.setLineDash([])}
if(showBox||view==='labels'){const a=p(b.x-.12,0,b.z-.12),c=p(b.x+b.w+.12,b.h+.35,b.z+b.d+.12);ctx.strokeStyle='#a3edd8';ctx.lineWidth=1.7;ctx.setLineDash([5,4]);const corners=[[b.x,0,b.z],[b.x+b.w,0,b.z],[b.x+b.w,0,b.z+b.d],[b.x,0,b.z+b.d],[b.x,b.h+.25,b.z],[b.x+b.w,b.h+.25,b.z],[b.x+b.w,b.h+.25,b.z+b.d],[b.x,b.h+.25,b.z+b.d]].map(v=>p(...v));[[0,1],[1,2],[2,3],[3,0],[4,5],[5,6],[6,7],[7,4],[0,4],[1,5],[2,6],[3,7]].forEach(([a,b])=>{ctx.beginPath();ctx.moveTo(corners[a].x,corners[a].y);ctx.lineTo(corners[b].x,corners[b].y);ctx.stroke()});ctx.setLineDash([]);const label=p(b.x+b.w/2,b.h+.9,b.z);ctx.fillStyle='#b7eddf';ctx.font='13px monospace';ctx.textAlign='center';ctx.fillText('bungalow',label.x,label.y)}
if(phase==='validator'&&blockers(scene).length){const t=blockers(scene)[0],q=p(t.x,2.5,t.z);ctx.fillStyle='#f0b48c';ctx.font='14px Arial';ctx.textAlign='center';ctx.fillText('view blocked',q.x,q.y)}
}
async function generate(){if(running)return;button.classList.remove("demo-invite");running=true;button.disabled=true;selector.disabled=true;button.textContent='Crew working…';complete.clear();layers.clear();points=[];showBox=false;const initialSeed=Math.floor(Date.now()%100000);scene=specFor(selector.value,initialSeed);document.querySelector('#scene-seed').textContent='Seed '+initialSeed;
try{status('planner','Planner turns the request into a scene specification.','Track layout, shelter dimensions, sensor position, and seed.');record();await delay(800);complete.add('planner');status('builder','Builder assembles the geometry.','One scene, built in a controlled sequence.');layers.add('track');draw();await delay(550);layers.add('shelter');draw();await delay(550);layers.add('trees');layers.add('sensor');draw();await delay(600);complete.add('builder');status('validator','Validator checks the sensor’s view.','The demo checks tree distance from the sensor-to-shelter line.');await delay(800);
while(blockers(scene).length&&scene.repairs<3){status('repair','A tree blocks the shelter. Repair moves it aside.','Failed check → targeted edit → validation again.');for(const t of blockers(scene)){t.x+=2.1;t.z+=1.3}scene.repairs++;record();await delay(900);complete.add('repair');status('validator','Validator checks the repaired scene.','The sensor-to-shelter line is checked again.');await delay(650)}
if(blockers(scene).length)throw Error('The view is still blocked after three repairs.');complete.add('validator');if(!complete.has('repair')){const el=document.querySelector('[data-agent="repair"] i');el.textContent='–';el.setAttribute('aria-label','Not needed')}
status('sensor','Sensor creates a visual point-cloud preview.','This is a geometric illustration, not a physical LiDAR simulation.');sampleCloud();draw();await delay(1000);complete.add('sensor');status('dataset','Dataset agent checks dimensions and sample points.','Positive box dimensions and a non-empty point preview are required.');if(!points.length||scene.shelter.w<=0||scene.shelter.h<=0||scene.shelter.d<=0)throw Error('Dataset checks failed.');await delay(750);complete.add('dataset');showBox=true;status('exporter','Exporter pairs the scene with its object label.','The label uses the same scene coordinates and shelter dimensions.');await delay(750);complete.add('exporter');status('done','Multimodal sample ready. Image, points, and label aligned.',`${points.length} visual sample points · ${scene.repairs} repair${scene.repairs===1?'':'s'} · seed ${initialSeed}`);record();
}catch(e){status('idle','Manual review needed.',e.message);record()}finally{running=false;button.disabled=false;selector.disabled=false;button.textContent='Generate another scene →'}}

function sampleCloud(){
 points=[];
 const add=(x,y,z,color)=>points.push({x,y,z,color});
 const surface=(x,y,z,w,h,d,color)=>{const step=.12;for(let a=0;a<=w;a+=step)for(let b=0;b<=d;b+=step)add(x+a,y+h,z+b,color);for(let a=0;a<=w;a+=step)for(let b=0;b<=h;b+=step){add(x+a,y+b,z,color);add(x+a,y+b,z+d,color)}for(let a=0;a<=d;a+=step)for(let b=0;b<=h;b+=step){add(x,y+b,z+a,color);add(x+w,y+b,z+a,color)}};
 const b=scene.shelter;surface(b.x,0,b.z,b.w,b.h,b.d,'#f2c780');surface(b.x-.16,b.h,b.z-.16,b.w+.32,.25,b.d+.32,'#f2c780');
 for(let x=-4.8;x<4.8;x+=.22)for(let z=-3.5;z<3.5;z+=.22)add(x,-.04,z,'#477e79');
 for(let i=0;i<60;i++){const z=-3.2+i*.105,o=scene.curved?Math.sin(i/59*2.2)*1.1:0;add(-3.38+o,.2,z,'#c5e9f3');add(-2.35+o,.2,z,'#c5e9f3')}
 scene.trees.forEach(t=>surface(t.x-t.r*.7,1,t.z-t.r*.7,t.r*1.6,1.1,t.r*1.6,'#81c691'));
}
function readout(){const el=document.querySelector('#cloud-readout');if(el)el.textContent=(view==='cloud'?points.length.toLocaleString()+' points · gold: shelter · green: vegetation':view==='labels'?'bungalow · 3D bounding box':'Scene / image')+' · sample '+scene.seed;}
document.querySelectorAll('[data-view]').forEach(el=>el.addEventListener('click',()=>{view=el.dataset.view;document.querySelectorAll('[data-view]').forEach(b=>b.setAttribute('aria-pressed',String(b===el)));if(!points.length&&!running)sampleCloud();readout();draw()}));
document.querySelector('#point-size').addEventListener('input',e=>{pointSize=Number(e.target.value);draw()});
document.querySelector('#reset-scene-view').onclick=()=>{angle=-.62;zoom=1;draw()};
canvas.style.touchAction='none';canvas.addEventListener('wheel',e=>{e.preventDefault();zoom=Math.max(.65,Math.min(2,zoom-e.deltaY*.001));draw()},{passive:false});
canvas.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','+','-','='].includes(e.key))return;e.preventDefault();if(e.key==='ArrowLeft')angle-=.1;else if(e.key==='ArrowRight')angle+=.1;else zoom=Math.max(.65,Math.min(2,zoom+(['ArrowUp','+','='].includes(e.key)?.1:-.1)));draw()});

function resize(){const r=canvas.getBoundingClientRect();width=r.width;height=r.height;const dpr=Math.min(devicePixelRatio,2);canvas.width=width*dpr;canvas.height=height*dpr;ctx.setTransform(dpr,0,0,dpr,0,0);draw()}
scene=specFor(selector.value,1042);layers=new Set(["track","shelter","trees","sensor"]);document.querySelector("#scene-stage").textContent="Scene preview";sampleCloud();record();new ResizeObserver(resize).observe(canvas);button.onclick=generate;let drag=null;canvas.addEventListener('pointerdown',e=>{drag={x:e.clientX,angle};canvas.setPointerCapture(e.pointerId)});canvas.addEventListener('pointermove',e=>{if(!drag)return;angle=Math.max(-1.2,Math.min(-.1,drag.angle+(e.clientX-drag.x)*.006));draw()});canvas.addEventListener('pointerup',()=>drag=null);canvas.addEventListener('pointercancel',()=>drag=null);resize();})();
